function Root(){const marker=import.meta.env.DEV&&import.meta.env.VITE_TODO_IDB_PILOT==='1'&&!native&&location.hostname==='127.0.0.1'&&location.port==='4178'?(sessionStorage.getItem('todo-idb-pilot')==='synthetic-legacy-compatible'?'synthetic-legacy-compatible':(localStorage.getItem('todo-shard-pilot-guard')==='1'||localStorage.getItem('todo-shard-switch-protocol')!==null)?'synthetic-v2':sessionStorage.getItem('todo-idb-pilot')):null;const Pilot=marker==='synthetic-legacy-compatible'?WebCompatibleLegacy:marker==='synthetic-only'?WebWorkspacePilot:marker==='synthetic-v2'?WebShardPilot:null;return Pilot?<Suspense fallback={<div role="status">加载隔离存储试验…</div>}><Pilot render={hydration=><App session={null} hydration={hydration}/>}/></Suspense>:<ProductionRoot/>}
createRoot(document.getElementById('root')).render(<Root/>);

